```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
## TOP-LEVEL: ASSESSMENT, TEST
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve learning. The corpus states assessment is 'often used interchangeably with test but is not limited to tests', hence Test is modeled as a subclass, not as equivalent." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination" , "exam" , "evaluation" ;
  rdfs:comment "An examination (exam/evaluation) or test is an educational assessment intended to measure knowledge, skill, aptitude, etc. The corpus treats 'test', 'exam' and 'examination' as synonyms." .

ea:AssessmentInstrument a owl:Class ;
  rdfs:label "AssessmentInstrument" .

ea:AssessmentContext a owl:Class ;
  rdfs:label "AssessmentContext" .

ea:RealisticContext a owl:Class ;
  rdfs:subClassOf ea:AssessmentContext .

ea:LearningOutcome a owl:Class ;
  rdfs:label "LearningOutcome" .

ea:IntendedLearningOutcome rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated with 'aims' in course descriptions." .
ea:MeasuredLearningOutcome rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated with 'objectives' in course descriptions." .
ea:UnintendedLearningOutcome rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Beneficial outcomes that were neither planned nor sought." .
[] a owl:AllDisjointClasses ; owl:members ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

#################################################################
## OBJECT / DATA PROPERTIES (generic)
#################################################################

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:hasInstrument a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AssessmentInstrument .

ea:hasAssessmentContext a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AssessmentContext .

ea:hasComponent a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Assessment .
ea:isComponentOf a owl:ObjectProperty ; owl:inverseOf ea:hasComponent .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:AssessmentItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:Test .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:AnswerOption .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:AnswerOption .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:hasStem a owl:DatatypeProperty ;
  rdfs:domain ea:AssessmentItem ; rdfs:range xsd:string .
ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .
ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .
ea:hasItemCount a owl:DatatypeProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:AnswerOption a owl:Class ; rdfs:label "AnswerOption" .

#################################################################
## AXIS 1: GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class .
ea:LearnerGranularity rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity rdfs:subClassOf ea:GranularityLevel .
ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

#################################################################
## AXIS 2: PURPOSE (placement / formative / summative / diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment" , "initial assessment" , "threshold knowledge test" , "TKT" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "educative assessment" , "assessment for learning" , "classroom assessment" , "formative evaluation" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "assessment of learning" , "summative evaluation" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage enumerates Placement, Formative, Summative and Diagnostic as four coordinate (pairwise-disjoint) purpose categories (modeled via the disjoint PurposeCategory partition); another passage states 'A common form of formative assessment is diagnostic assessment', which is modeled as DiagnosticAssessment rdfs:subClassOf FormativeAssessment. Given the functional hasPurpose property and the disjointness of FormativePurpose/DiagnosticPurpose, these two axioms jointly entail DiagnosticAssessment is unsatisfiable -- this contradiction is preserved deliberately to reflect the corpus disagreement." .

ea:SelfAssessment rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
## AXIS 3: OBJECTIVITY (objective / subjective)
#################################################################

ea:hasObjectivity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ObjectivityCategory .

ea:ObjectivityCategory a owl:Class .
ea:ObjectiveCategory rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveAssessment a owl:Class ;
  rdfs:comment "A form of questioning that has a single correct answer." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveAssessment a owl:Class ;
  rdfs:comment "A form of questioning that may have more than one correct answer." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

#################################################################
## AXIS 4: REFERENCING (criterion / norm / ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencing rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  rdfs:comment "Self-comparison either in the same domain over time or across domains within the same student." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:MasteryTest rdfs:subClassOf ea:CriterionReferencedTest ;
  rdfs:comment "Many, but not all, criterion-referenced tests involve a cutscore and are called mastery tests." .

#################################################################
## TEST SCORE INTERPRETATION (distinct axis on Test)
#################################################################

ea:TestScoreInterpretation a owl:Class .
ea:NormReferencedScoreInterpretation rdfs:subClassOf ea:TestScoreInterpretation .
ea:CriterionReferencedScoreInterpretation rdfs:subClassOf ea:TestScoreInterpretation .
[] a owl:AllDisjointClasses ; owl:members ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

ea:hasScoreInterpretation a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:TestScoreInterpretation .

#################################################################
## AXIS 5: FORMALITY (formal / informal)
#################################################################

ea:hasFormality a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class .
ea:FormalCategory rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] .

#################################################################
## AXIS 6: LOCUS OF CONTROL (internal / external)
#################################################################

ea:hasLocus a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class .
ea:InternalLocus rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] .

#################################################################
## AXIS 7: STANDARDIZATION (Test)
#################################################################

ea:hasStandardization a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] .

ea:TestAdaptation a owl:Class ;
  rdfs:comment "A change to testing conditions for a test-taker." .
ea:Accommodation rdfs:subClassOf ea:TestAdaptation ;
  rdfs:comment "Improves fairness without undermining the point of the assessment; the result remains a StandardizedTest." .
ea:Modification rdfs:subClassOf ea:TestAdaptation ;
  rdfs:comment "Undermines the purpose of the test; the result is no longer a StandardizedTest." .
[] a owl:AllDisjointClasses ; owl:members ( ea:Accommodation ea:Modification ) .

#################################################################
## AXIS 8: STAKES (Test)
#################################################################

ea:hasStakes a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesCategory rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest a owl:Class ;
  rdfs:comment "A test with a desired reward for good performance / used to make important decisions about students, educators, schools, or districts." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

#################################################################
## AXIS 9: TEST FORMAT (written / oral / practical)
#################################################################

ea:hasFormat a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:FormatCategory .

ea:FormatCategory a owl:Class .
ea:WrittenFormat rdfs:subClassOf ea:FormatCategory .
ea:OralFormat rdfs:subClassOf ea:FormatCategory .
ea:PracticalFormat rdfs:subClassOf ea:FormatCategory .
ea:FormatCategory owl:disjointUnionOf ( ea:WrittenFormat ea:OralFormat ea:PracticalFormat ) .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test [ a owl:Restriction ; owl:onProperty ea:hasFormat ; owl:someValuesFrom ea:WrittenFormat ] ) ] .
ea:OralTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test [ a owl:Restriction ; owl:onProperty ea:hasFormat ; owl:someValuesFrom ea:OralFormat ] ) ] .
ea:PracticalTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test [ a owl:Restriction ; owl:onProperty ea:hasFormat ; owl:someValuesFrom ea:PracticalFormat ] ) ] .

#################################################################
## NAMED TEST KINDS
#################################################################

ea:CompetitiveExamination a owl:Class ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers are selected." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
     [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] .

ea:Quiz rdfs:subClassOf ea:Test , ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; usually low-stakes and formative." .

ea:MidtermExam rdfs:subClassOf ea:Test ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "A type of formative or summative assessment given near the middle of a term." .

ea:FinalExam rdfs:subClassOf ea:Test , ea:SummativeAssessment ;
  rdfs:comment "A final review and assessment of topics covered, typically at the end of a course." .

ea:InterimAssessment rdfs:subClassOf ea:Assessment ;
  skos:altLabel "benchmark assessment" ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Some educators consider interim/benchmark tests formative (diagnostic use); others consider them summative. Both views are modeled via the union superclass." .

ea:ScreeningAssessment rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to determine whether students need specialized assistance or are ready to begin a course/program; conceptually overlaps with PlacementAssessment." .

ea:CommonAssessment rdfs:subClassOf ea:Assessment ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Used across a school/department to ensure consistent evaluation; may be formative or summative." .

#################################################################
## PERFORMANCE-BASED / AUTHENTIC / PORTFOLIO / CONTINUOUS
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance assessment" , "performance test" ;
  rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; described as 'similar to summative assessment'." .

ea:PerformanceOutcome a owl:Class .
ea:Product rdfs:subClassOf ea:PerformanceOutcome .
ea:Performance rdfs:subClassOf ea:PerformanceOutcome .
ea:PerformanceOutcome owl:disjointUnionOf ( ea:Product ea:Performance ) .

ea:hasOutcome a owl:ObjectProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceOutcome .

ea:PerformanceTest rdfs:subClassOf ea:Test , ea:PerformanceBasedAssessment ;
  rdfs:comment "An assessment requiring the examinee to actually perform a task or activity, e.g. a behind-the-wheel driving test." .

ea:AuthenticAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasAssessmentContext ; owl:someValuesFrom ea:RealisticContext ] ) ] ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school. The corpus also states 'performance assessments may also be called authentic assessments', suggesting overlap with PerformanceBasedAssessment without full equivalence; both views are retained." .

ea:Portfolio rdfs:subClassOf ea:AssessmentInstrument ;
  skos:altLabel "e-portfolio" , "digital portfolio" ;
  rdfs:comment "A compilation of academic work and other educational evidence." .

ea:PortfolioAssessment rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Assessment
     [ a owl:Restriction ; owl:onProperty ea:hasInstrument ; owl:someValuesFrom ea:Portfolio ] ) ] .

ea:ContinuousAssessment rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates progress throughout a prescribed course; often as an alternative to a final-examination system; will often include some form of formative assessment." .

[] a owl:Axiom ;
   owl:annotatedSource ea:ContinuousAssessment ;
   owl:annotatedProperty ea:hasComponent ;
   owl:annotatedTarget ea:FormativeAssessment .

ea:ContinuousAssessment rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasComponent ; owl:someValuesFrom ea:FormativeAssessment ] .

#################################################################
## RUBRIC / GRADING
#################################################################

ea:Rubric rdfs:subClassOf ea:AssessmentInstrument ;
  skos:altLabel "scoring guide" , "checklist" .

ea:HolisticRubric rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric rdfs:subClassOf ea:Rubric .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .
ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: one passage lists holistic, analytic and developmental rubrics as coordinate alternatives ('Rubrics can be classified as holistic, analytic, or developmental'), modeled as pairwise disjoint; the same passage also states developmental rubrics are 'a subset of analytical rubrics', modeled as an additional subClassOf axiom. Both are retained even though they create an inconsistency given the disjointness axiom above." .

ea:GradingMethod a owl:Class .
ea:HolisticGrading rdfs:subClassOf ea:GradingMethod ;
  skos:altLabel "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality; treats the composition as a whole." .
ea:AnalyticGrading rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Takes more, separately-weighted factors into account than holistic grading." .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Trains raters to score against a rubric with traits scaled to achievement levels; remains holistic at heart but approaches analytic scoring." .

#################################################################
## ASSESSMENT ITEMS
#################################################################

ea:AssessmentItem a owl:Class ;
  skos:altLabel "test item" , "question" .

ea:ObjectiveItem rdfs:subClassOf ea:AssessmentItem .
ea:SubjectiveItem rdfs:subClassOf ea:AssessmentItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:TrueFalseItem rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ" , "multiple choice question" , "objective response" .
ea:MultipleResponseItem rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem rdfs:subClassOf ea:ObjectiveItem .
[] a owl:AllDisjointClasses ; owl:members
  ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question" , "FRQ" .
[] a owl:AllDisjointClasses ; owl:members ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:FillInTheBlankItem rdfs:subClassOf ea:AssessmentItem .
ea:CalculationItem rdfs:subClassOf ea:AssessmentItem ;
  rdfs:comment "Mathematics/calculation questions that do not fall into the other item-format categories." .

ea:MultipleChoiceItem owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
   ea:AssessmentItem
   [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:AnswerOption ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
   ea:AssessmentItem
